<?php
if(!tableExists('social_jobs') || !tableExists('social_accounts') || !tableExists('social_profiles')) {echo '<div class="notice error">Database update required. Back up the database, then run <code>php bin/upgrade.php</code> from the project folder. Your existing content is preserved.</div>';return;}
$profiles=socialProfiles();$accounts=query('SELECT channel,account_id,enabled,updated_at FROM social_accounts')->fetchAll(PDO::FETCH_UNIQUE | PDO::FETCH_ASSOC);
?>
<div class="admin-card"><h2>Public social profile links</h2><p>These links appear in the website footer. Leave a network blank to hide it. Profile links do not authorize posting.</p><form method="post"><?=csrf()?><input type="hidden" name="action" value="profiles"><?php foreach(socialChannels() as $key=>$label): ?><label><?=e($label)?> profile URL<input type="url" name="<?=e($key)?>" maxlength="500" value="<?=e($profiles[$key] ?? '')?>" placeholder="https://…"></label><?php endforeach ?><button class="button">Save profile links</button></form></div>
<div class="admin-card"><h2>Facebook & Instagram publishing accounts</h2><p>Developer-assisted setup: use authorized Meta access tokens for a Facebook Page and an Instagram professional account linked to a Facebook Page (Facebook Login flow). Store a Page token with the relevant permissions. Tokens are encrypted and never shown again. Saving a token means configured, not verified.</p><p><a class="text-link" href="<?=e(appUrl('/admin.php?tab=help#social-help'))?>">Read publishing setup and permission requirements ↗</a></p></div>
<?php foreach(['facebook'=>'Facebook Page','instagram'=>'Instagram professional account'] as $channel=>$label): $account=$accounts[$channel] ?? null; ?>
<div class="admin-card"><span class="status <?=$account && $account['enabled']?'live':'draft'?>"><?=$account?($account['enabled']?'Configured · enabled · unverified':'Configured · disabled'):'Not configured'?></span><h2><?=e($label)?></h2><form method="post" autocomplete="off"><?=csrf()?><input type="hidden" name="action" value="account"><input type="hidden" name="channel" value="<?=e($channel)?>"><label><?=e($channel==='facebook'?'Page ID':'Instagram professional account ID')?><input name="account_id" inputmode="numeric" pattern="[0-9]{5,80}" maxlength="80" value="<?=e($account['account_id'] ?? '')?>" required></label><label>Access token <?=$account?'(leave blank to keep existing token)':''?><input type="password" name="access_token" autocomplete="new-password" maxlength="4000" <?=!$account?'required':''?>><small>Do not paste passwords, app secrets or website login credentials. Account changes require a new access token.</small></label><label class="check"><input type="checkbox" name="enabled" <?=$account && $account['enabled']?'checked':''?>><span>Enable publishing to this authorized account</span></label><button class="button">Save <?=e($label)?></button></form><?php if($account): ?><form method="post" class="spaced-form" data-confirm="Disconnect this publishing account and cancel its pending jobs?"><?=csrf()?><input type="hidden" name="channel" value="<?=e($channel)?>"><button class="danger" name="action" value="disconnect">Disconnect account</button></form><?php endif ?></div>
<?php endforeach ?>
<div class="admin-card"><h2>Queue a website post</h2><p>The caption and photo are frozen when queued. The worker sends to each selected network independently. A website edit does not modify an existing social post. Images need a publicly accessible HTTPS URL; Meta cannot reach localhost.</p><form method="post"><?=csrf()?><input type="hidden" name="action" value="queue"><label>Published website post<select name="post_id" required><option value="">Select a post</option><?php foreach(query('SELECT id,title FROM posts WHERE published=1 ORDER BY id DESC LIMIT 200')->fetchAll() as $post): ?><option value="<?=e($post['id'])?>"><?=e($post['title'])?></option><?php endforeach ?></select></label><label>Publish to<select name="channel"><option value="facebook">Facebook Page</option><option value="instagram">Instagram</option></select></label><button class="button">Queue automatic publishing ↗</button></form><p>Server worker: <code>php bin/publish-social.php</code>. Ask your hosting administrator to run it every minute. It sends up to 5 due jobs per run. Local previews do not start a background publisher automatically.</p></div>
<h2>Publishing history</h2><p>Up to 100 latest jobs. “Sent” has a provider ID, or was explicitly verified by an administrator. Queueing alone is not proof of publication.</p>
<?php $jobs=query("SELECT j.*,COALESCE(p.title,'Deleted website post') AS title FROM social_jobs j LEFT JOIN posts p ON p.id=j.post_id ORDER BY j.id DESC LIMIT 100")->fetchAll();if(!$jobs): ?><div class="admin-card">No publishing jobs yet.</div><?php endif ?>
<?php foreach($jobs as $job): ?><article class="admin-card"><span class="status <?=$job['status']==='sent'?'live':'draft'?>"><?=e(str_replace('_',' ',$job['status']))?></span><h3><?=e(ucfirst($job['channel']).' · '.$job['title'])?></h3><p class="preserve"><?=e($job['caption'])?></p><p><small>Job #<?=e($job['id'])?> · Account <?=e($job['account_id'])?> · Created <?=e($job['created_at'])?><?php if($job['remote_id']): ?> · Provider ID: <?=e($job['remote_id'])?><?php endif ?></small></p><?php if($job['error_message']): ?><p class="notice"><?=e($job['error_message'])?></p><?php endif ?>
<?php if(in_array($job['status'],['pending','failed'],true)): ?><form method="post"><?=csrf()?><input type="hidden" name="job_id" value="<?=e($job['id'])?>"><button class="secondary" name="action" value="cancel">Cancel job</button></form><?php endif ?>
<?php if(in_array($job['status'],['failed','needs_review'],true)): ?><form method="post" class="spaced-form"><?=csrf()?><input type="hidden" name="job_id" value="<?=e($job['id'])?>"><label class="check"><input type="checkbox" name="checked_account" value="yes" required><span>I checked the real account and confirmed this post was not published.</span></label><button class="secondary" name="action" value="retry">Retry checked job</button></form><?php endif ?>
<?php if($job['status']==='needs_review'): ?><form method="post" class="spaced-form"><?=csrf()?><input type="hidden" name="job_id" value="<?=e($job['id'])?>"><label class="check"><input type="checkbox" name="checked_account" value="yes" required><span>I checked the real account and verified this post is already published.</span></label><button class="secondary" name="action" value="resolve">Mark as manually verified</button></form><?php endif ?></article><?php endforeach ?>
